// Üretilen dosya: tool/ozgun/uret.py. Edebiyat · Edebî türler, şiir bilgisi, söz sanatları ve anlatım teknikleri (orta).
const ozLiterature4Orta = <(String, String, List<String>, String)>[
  ('Öğretici metinleri sanatsal metinlerden ayıran en temel özellik hangisidir?', 'Dilin daha çok göndergesel işlevde kullanılması', ['Metinde mutlaka bir anlatıcının bulunması', 'Olayların kronolojik sırayla verilmesi', 'Sözcüklerin yan ve mecaz anlamlarıyla kullanılması'], 'Öğretici metinler bilgi aktarmayı amaçladığı için dil göndergesel (bilgilendirici) işlevde kullanılır; sanatsal metinlerde ise şiirsel işlev öne çıkar.'),
  ('Tiyatro hangi gerekçeyle \'göstermeye bağlı\' metinler arasında sayılır?', 'Olaylar sahnede canlandırılarak sunulur', ['Metnin tamamı manzum olarak yazılmak zorundadır', 'Anlatıcı olayları geriye dönüşlerle aktarır', 'Her eserde mutlaka bir ders verilmesi amaçlanır'], 'Tiyatroda olaylar bir anlatıcının aracılığı olmadan oyuncular tarafından sahnede canlandırılır; bu yüzden gösterme esasına dayanır.'),
  ('Bir öğretmen, öğrencilerinden \'kurmaca olmayan ama anlatıya dayanan\' bir tür örneği istemiştir. Hangi öğrencinin yanıtı bu ölçüte uyar?', 'Gezi yazısı getiren öğrenci', ['Roman getiren öğrenci', 'Masal derleyip getiren öğrenci', 'Fabl getiren öğrenci'], 'Gezi yazısı gerçek gözlemlere dayanır, yine de bir gezinin anlatımını içerir. Roman, masal ve fabl kurmaca anlatılardır.'),
  ('Roman ile hikâyeyi ayırt etmede kullanılan ölçütlerden hangisi en güvenilirdir?', 'Olayın kapsamı ve kişi kadrosunun genişliği', ['Anlatımda düz yazının kullanılıp kullanılmadığı', 'Metinde zaman ve mekân unsurunun bulunması', 'Yazarın olayları hayal gücüyle kurgulaması'], 'Roman ve hikâye düz yazı, kurmaca ve zaman-mekân unsurlarını paylaşır; ayrımı asıl olarak olayın kapsamı ve kişi sayısındaki genişlik sağlar.'),
  ('Toplumun düşük kesiminden gelen, kurnazlığıyla hayatta kalmaya çalışan bir kahramanın serüvenlerini epizotlar hâlinde anlatan roman türü hangisidir?', 'Pikaresk roman', ['Epistolar roman', 'Psikolojik roman', 'Bildungsroman'], 'Pikaresk roman, İspanyolca \'pícaro\' (serseri, kurnaz) sözünden gelir; alt tabakadan bir kahramanın birbirine gevşekçe bağlı serüvenlerini anlatır.'),
  ('Bir kahramanın çocukluktan olgunluğa uzanan kişilik ve bilinç gelişimini merkeze alan roman türüne ne ad verilir?', 'Oluşum (eğitim) romanı', ['Pikaresk roman', 'Polisiye roman', 'Tezli (ideolojik) roman'], 'Almanca \'Bildungsroman\' karşılığı olan oluşum romanı, kahramanın zihinsel ve ahlaki gelişimini konu alır.'),
  ('Yazarın belirli bir düşünceyi ya da toplumsal görüşü savunmak için olayları ve kişileri bu amaca göre biçimlendirdiği romana ne denir?', 'Tezli roman', ['Macera romanı', 'Polisiye roman', 'Fantastik roman'], 'Tezli romanda yazar bir düşünceyi kanıtlamaya çalışır; olay ve kişiler bu tezin hizmetindedir.'),
  ('Bir romanın teması ile konusu arasındaki ilişki için aşağıdakilerden hangisi doğrudur?', 'Konu olayların özüdür, tema ise ana düşüncedir', ['Konu ve tema aynı kavramın iki farklı adıdır', 'Tema olayların sırası, konu ise kişilerin sayısıdır', 'Konu yalnız şiirde, tema yalnız romanda bulunur'], 'Konu \'ne anlatılıyor\' sorusunun yanıtıdır; tema ise metnin ardındaki ana düşünce ya da duygu (örneğin yalnızlık, aşk, ihanet) olur.'),
  ('Bir romanda olaylar ilerledikçe değişmeyen, tek bir özelliğin abartılarak temsil edildiği kişiye ne ad verilir?', 'Düz (yassı) karakter', ['Yuvarlak (çok yönlü) karakter', 'Dinamik karakter', 'Çok boyutlu karakter'], 'Düz karakter tek boyutludur ve eser boyunca değişmez; yuvarlak ya da dinamik karakterler gelişim gösterir.'),
  ('Bir romanda başlangıçta bencil olan kahraman, yaşadığı kayıplar sonucunda fedakâr birine dönüşüyor. Bu kahraman için hangi nitelendirme en uygundur?', 'Dinamik karakter', ['Tip', 'Statik (değişmeyen) karakter', 'Yassı karakter'], 'Olayların etkisiyle değişip gelişen karakter dinamik karakterdir. Tip ve statik karakter değişmez.'),
  ('İdeal bir toplum düzenini tasarlayan kurmaca eserlere \'ütopya\' denir. Baskıcı, korkutucu bir gelecek toplumunu tasarlayan eserlere ne ad verilir?', 'Distopya', ['Pastoral (kır) şiiri', 'Alegori', 'Parodi'], 'Distopya, ütopyanın karşıtıdır; özgürlüğün kısıtlandığı, karamsar bir toplum düzenini anlatır.'),
  ('Maupassant tarzı hikâyenin en belirgin özelliği hangisidir?', 'Merak öğesine ve kesin bir sona dayanması', ['Olaydan çok bir anın ya da durumun izleniminin verilmesi', 'Sonun bilinçli olarak belirsiz ve açık bırakılması', 'Olayın yerine kahramanın iç sesinin aktarılması'], 'Olay hikâyesi olarak da bilinen Maupassant tarzında merak ve kesin bir sonuçla biten klasik plan esastır.'),
  ('Bir hikâyede bir memur sabah otobüs durağında beklerken etrafındaki insanları izliyor, kafasından geçenler anlatılıyor ve hikâye o otobüse binince bitiyor. Bu metin hangi hikâye tipine daha yakındır?', 'Durum hikâyesi', ['Olay hikâyesi', 'Polisiye hikâye', 'Macera hikâyesi'], 'Belirgin bir olay ve çözüm yoktur; bir anın ve ruh hâlinin kesiti verilmiştir. Bu, durum (Çehov tarzı) hikâyenin özelliğidir.'),
  ('Romanla hikâye arasında yer alan, hikâyeden uzun romandan kısa anlatı türüne Batı edebiyatında ne ad verilir?', 'Novella', ['Fabl', 'Skeç', 'Vodvil'], 'Novella, uzunluk ve kapsam bakımından hikâye ile roman arasında kalan anlatı türüdür.'),
  ('Hikâye ile masalı ayırt etmeyi sağlayan en belirleyici ölçüt aşağıdakilerden hangisidir?', 'Olayların gerçekleşebilir olup olmaması', ['Metinde kişi ve yer adlarının bulunup bulunmaması', 'Düz yazıyla yazılıp yazılmaması', 'Bir anlatıcının olup olmaması'], 'Hikâyede olaylar gerçekleşmiş ya da gerçekleşebilir niteliktedir; masalda ise olağanüstü, gerçek dışı olaylar vardır. Diğer unsurlar iki türde de bulunabilir.'),
  ('Masallarda zaman ve mekânın \'evvel zaman içinde, kalbur saman içinde\' gibi belirsiz ifadelerle verilmesinin temel işlevi nedir?', 'Anlatıyı her yere ve çağa uyarlanabilir kılmak', ['Olayların tarihini kesin olarak belirlemek', 'Anlatıcının kim olduğunu tanıtmak', 'Okura bilimsel bilgi aktarmak'], 'Belirsiz zaman ve mekân, masalı herhangi bir yere ve döneme bağlamadan, her toplumun benimseyebileceği bir anlatıya dönüştürür.'),
  ('Masallarda sıkça görülen \'üç\' sayısının (üç kardeş, üç elma, üç sınav gibi) tekrar edilmesi neye örnektir?', 'Kalıplaşmış motif kullanımına', ['Bilinç akışı ve iç monolog tekniğine', 'Geriye dönüş tekniğine', 'Gözlemci anlatıcıya'], 'Üç sayısı, sihirli nesneler ve sınavlar gibi tekrarlanan öğeler masalların kalıp motifleridir.'),
  ('Fablın masaldan ayrıldığı en temel nokta hangisidir?', 'Hayvan kahramanlarla açık bir ders vermesi', ['Olayların gerçek dışı olması', 'Belirsiz bir zaman ve mekânda geçmesi', 'Sözlü gelenekte de bulunabilmesi'], 'Masal da gerçek dışıdır ve belirsiz zaman-mekân kullanır; fablı ayıran, hayvan ya da cansız kahramanlar aracılığıyla doğrudan ahlaki ders vermesidir.'),
  ('Fabllarda hayvanların belli insan tiplerini temsil etmesi (tilki kurnazı, aslan güçlüyü temsil eder gibi) fablı hangi anlatım yoluna yaklaştırır?', 'Alegori', ['Bilinç akışı', 'Röportaj', 'Biyografi'], 'Fabl, hayvan kişileri aracılığıyla insanlara ilişkin bir anlamı dolaylı olarak anlatan alegorik bir türdür.'),
  ('Halk arasında sözlü olarak doğup gelişen ve sonradan derlenen destanlar ile bir şairin bilinçli olarak yazdığı destanlar nasıl adlandırılır?', 'Doğal destan ve yapma destan', ['Lirik destan ve epik destan', 'Kısa destan ve uzun destan', 'Dinî destan ve din dışı destan'], 'Anonim, sözlü gelenekte oluşanlara doğal destan; belli bir şairin kaleme aldıklarına yapma (suni) destan denir.'),
  ('Destanların oluşum aşamaları hangi seçenekte doğru sırayla verilmiştir?', 'Doğuş, yayılma, derleme', ['Derleme, doğuş, yayılma, unutulma', 'Yayılma, derleme, doğuş', 'Doğuş, derleme, yayılma'], 'Destan önce bir olay etrafında doğar, sözlü olarak yayılır, en son bir derleyici tarafından yazıya geçirilir.'),
  ('Destan kahramanlarının doğaüstü bir doğum, olağanüstü güç ve uzun ömür gibi özelliklerle anlatılmasının temel nedeni nedir?', 'Kahramanın toplumun ideallerini ve gücünü simgelemesi', ['Olayların bilimsel olarak açıklanmak istenmesi', 'Anlatının kısa ve yalın tutulmak istenmesi', 'Kahramanın sıradan bir birey olarak gösterilmek istenmesi'], 'Destan kahramanı bireyden çok toplumun sembolüdür; olağanüstü nitelikleri toplumun ideallerini ve gücünü yansıtır.'),
  ('Komedide gülmeyi olay ve durumlardan çok, kişilerin belirgin kusurlarıyla (cimrilik, kıskançlık, iki yüzlülük gibi) yaratan türe ne ad verilir?', 'Karakter komedisi', ['Entrika (olay) komedisi', 'Töre komedisi', 'Vodvil'], 'Karakter komedisinde gülünçlük bir kişinin abartılmış zaafından doğar.'),
  ('Bir komedide gülünçlük; kılık değiştirme, yanlış anlaşılmalar ve karışıklıklar gibi olayların düzenlenmesinden doğuyorsa bu tür nasıl adlandırılır?', 'Entrika komedisi', ['Karakter komedisi', 'Töre komedisi', 'Trajikomedi'], 'Entrika komedisinde gülme etkisi kişilerden çok olayların karmaşık ve şaşırtıcı biçimde örgülenmesinden kaynaklanır.'),
  ('Bir toplumun gelenek, görenek ve yaşayış biçimindeki çarpıklıkları alaya alan komedi türü hangisidir?', 'Töre komedisi', ['Entrika komedisi', 'Karakter komedisi', 'Dram'], 'Töre komedisi bir dönemin ya da toplumun alışkanlıklarını ve geleneklerini eleştirel bir güldürüyle işler.'),
  ('Abartılı durumlara ve fiziksel güldürüye dayanan, inandırıcılıktan çok kahkaha uyandırmayı amaçlayan hafif komedi türüne ne ad verilir?', 'Fars', ['Dram', 'Trajedi', 'Melodram'], 'Fars, kaba güldürü öğeleri ve abartılı durumlarla eğlendirmeyi hedefleyen bir komedi türüdür.'),
  ('Dram türünün klasik trajediye karşı getirdiği yeniliklerden hangisi doğrudur?', 'Kahramanların her sınıftan seçilebilmesi', ['Üç birlik kuralına sıkıca bağlı kalınması', 'Yalnız manzum dilin kullanılması', 'Olayların sahnede gösterilmesinin yasaklanması'], 'Dram, üç birlik kuralını ve soylu kahraman zorunluluğunu bırakmış; her toplumsal kesimden kişiyi sahneye taşımıştır.'),
  ('Bir tiyatro oyununda bir kişinin uzun ve kesintisiz konuşmasına ne ad verilir?', 'Tirad', ['Diyalog', 'Suflör', 'Dekor'], 'Tirad, oyun kişilerinden birinin karşısındakine yönelttiği uzun konuşmadır.'),
  ('\'Ben bu konuda yanılıyor olabilirim; ama bana öyle geliyor ki insan en çok kendi sesini dinlemekten korkar.\' Bu cümlenin ait olabileceği metin türü için en güçlü ipucu nedir?', 'Kişisel ve kesinlikten kaçınan bir bakış', ['Bir haberin 5N1K sorularıyla verilmesi', 'Olayların bir anlatıcı tarafından sırayla aktarılması', 'Sayısal verilere dayanılarak bir tezin kanıtlanması'], '\'Yanılıyor olabilirim, bana öyle geliyor\' gibi ifadeler kesinlikten kaçınan kişisel bir bakışı gösterir; bu da denemenin belirgin özelliğidir.'),
  ('Makalenin bölümleri için aşağıdakilerden hangisi doğrudur?', 'Tez girişte sunulur, gelişmede kanıtlanır', ['Giriş bölümünde yazar hayat hikâyesini anlatır', 'Gelişme bölümü yalnız diyaloglardan oluşur', 'Sonuç bölümünde yeni ve tartışmalı bir konu açılır'], 'Makale giriş-gelişme-sonuç planına göre yazılır: tez girişte sunulur, gelişmede desteklenir, sonuçta özetlenir.'),
  ('Sohbet türünde yazarın sık sık \'değil mi?\', \'ne dersiniz?\' gibi sorular sorması hangi amaca hizmet eder?', 'Okuru konuşmanın bir tarafı gibi hissettirmeye', ['Bilimsel bir sonucu verilerle kanıtlamaya', 'Olayların kronolojisini belirtmeye', 'Metne ölçü ve kafiye kazandırmaya'], 'Bu tür sorular okurla diyalog kuruluyormuş izlenimi yaratır ve sohbete özgü samimiyeti sağlar.'),
  ('Eleştirmenin bir eseri okurken edindiği kişisel izlenimleri ve beğenisini ön plana çıkardığı eleştiri anlayışına ne ad verilir?', 'İzlenimci (öznel) eleştiri', ['Bilimsel (yöntemli, nesnel) eleştiri', 'Biçimci eleştiri', 'Tarihsel eleştiri'], 'İzlenimci eleştiri, eserin eleştirmende uyandırdığı duygu ve izlenimleri temel alır.'),
  ('Bir eleştiri yazısının nesnel sayılabilmesi için aşağıdakilerden hangisine dikkat edilmesi gerekir?', 'Yargıların eserden örneklerle desteklenmesi', ['Eserin yazarının kişiliğine yönelik saldırı içermesi', 'Yalnızca eserin olumsuz yönlerinin vurgulanması', 'Eleştirmenin eseri hiç okumadan genel görüş bildirmesi'], 'Nesnel eleştiri, kanıta dayanan, ölçütleri belli ve hem olumlu hem olumsuz yönleri dengeli değerlendiren bir yaklaşımdır.'),
  ('Gezi yazısında en çok başvurulan iki anlatım biçimi hangileridir?', 'Betimleme ve öyküleme', ['Tartışma ve açıklama', 'Tanık gösterme ve sayısal veri', 'Diyalog ve monolog'], 'Gezi yazısında gezilen yerler betimlenir, gezi sırasındaki olaylar ise öyküleyici anlatımla aktarılır.'),
  ('Bir gezi yazısının yalnızca bir turizm broşüründen ayrılarak edebî değer kazanması için hangisi en önemlidir?', 'Yazarın özgün gözlem ve izlenimlerini yansıtması', ['Otel ve ulaşım fiyatlarının ayrıntılı olarak verilmesi', 'Gezilen yerin yalnızca haritadaki konumunun belirtilmesi', 'Yazının mümkün olduğunca kısa tutulması'], 'Gezi yazısını edebîleştiren, yazarın bakışı, duyarlılığı ve dilidir; salt bilgi aktarımı onu broşüre dönüştürür.'),
  ('Bir biyografinin güvenilir sayılması için aşağıdakilerden hangisi en gereklidir?', 'Bilgilerin doğrulanabilir kaynaklara dayanması', ['Kişinin yalnızca olumlu yönlerinin anlatılması', 'Olayların yazarın hayal gücüyle tamamlanması', 'Metnin şiirsel bir dille yazılması'], 'Biyografi gerçek bir hayatı anlattığı için kaynak ve belgeye dayalı olması, güvenilirliğin temel koşuludur.'),
  ('Bir yazarın başka bir yazara edebiyat ve sanat üzerine görüşlerini paylaştığı mektuplar hangi mektup türüne girer?', 'Edebî mektup', ['Resmî yazışma mektubu', 'İş mektubu', 'Dilekçe'], 'Sanat ve edebiyat konularının işlendiği, edebî değer taşıyan mektuplar edebî mektup olarak sınıflandırılır.'),
  ('Günlük çoğunlukla yazarın kendisi için yazılır. Bu durum günlüğün diline ve içeriğine en çok nasıl yansır?', 'İçten ve süslemesiz bir anlatım', ['Resmî ve kalıplaşmış bir dil kullanılır', 'Okura sürekli doğrudan seslenilir', 'Bilimsel terimler yoğun biçimde kullanılır'], 'Yazar kendisi için yazdığından kaygısızca ve içtenlikle yazar; bu da günlüğün doğal ve samimi dilini açıklar.'),
  ('Bir konunun, bir başkan yönetiminde uzmanlar tarafından dinleyiciler önünde farklı yönleriyle tartışıldığı ve izleyicilerin de sonunda soru sorabildiği sözlü anlatım türü hangisidir?', 'Panel', ['Münazara', 'Nutuk', 'Mülakat'], 'Panelde bir başkan ve konuşmacılar konuyu dinleyiciler önünde tartışır; sonunda dinleyicilerin katılımına izin verilir.'),
  ('Bilimsel bir konunun uzmanlarca birkaç gün sürebilen oturumlarda bildiriler hâlinde sunulup tartışıldığı toplantı türüne ne ad verilir?', 'Sempozyum', ['Panel', 'Münazara', 'Forum'], 'Sempozyum, bilimsel bir konunun birden çok uzmanın hazırladığı bildirilerle ele alındığı geniş kapsamlı toplantıdır.'),
  ('Bir konunun, bir başkan yönetiminde dinleyicilerin de doğrudan ve geniş biçimde katıldığı, toplumu ilgilendiren konuların tartışıldığı toplantı türüne ne ad verilir?', 'Forum', ['Sempozyum', 'Nutuk', 'Mülakat'], 'Forumda dinleyiciler tartışmanın aktif katılımcısıdır; çoğunlukla bir panelin ardından genel katılımla yapılır.'),
  ('Konferans ile söylevi karşılaştıran aşağıdaki yargılardan hangisi doğrudur?', 'Konferans bilgilendirir, söylev ise harekete geçirir', ['Söylev bilimsel bildirilerden oluşur, konferans ise jüri önünde yapılır', 'İkisi de mutlaka iki karşıt grup arasında yapılır', 'Konferansta konuşmacı yoktur, yalnız dinleyiciler konuşur'], 'Konferans bir uzmanın bir konuda bilgi aktardığı konuşmadır; söylev ise duygulara seslenen, harekete geçirmeyi amaçlayan konuşmadır.'),
  ('Dörtten fazla dizenin bir araya gelmesiyle oluşan nazım birimine genel olarak ne ad verilir?', 'Bent', ['Beyit', 'Dörtlük', 'Mısra'], 'Beşlik, altılık gibi dörtten fazla dizeden oluşan nazım birimlerine bent denir.'),
  ('Bir şiir 5 dizelik 3 bentten ve en sonda tek bir beyitten oluşuyor. Bu şiirin toplam dize sayısı kaçtır?', '17', ['15', '16', '18'], '3 bent x 5 dize = 15 dize; beyit 2 dize ekler; toplam 15 + 2 = 17 dize olur.'),
  ('Serbest şiirde nazım birimi için aşağıdakilerden hangisi doğrudur?', 'Dize ve bent sayısı şairin isteğine göre değişebilir', ['Her bendin tam olarak dört dizeden oluşması zorunluluğu', 'Yalnızca beyit kullanılabilir', 'Nazım birimi olarak sadece üçlük kabul edilir'], 'Serbest şiirde belirli bir nazım birimi zorunluluğu yoktur; bentlerin dize sayısı serbestçe değişebilir.'),
  ('\'Gün batarken / sular kızıl\' dizesinin ölçü ve durak yapısı hangi seçenekte doğru verilmiştir?', '8\'li (4+4)', ['7\'li (4+3)', '8\'li (5+3)', '9\'lu (4+5)'], 'Gün-ba-tar-ken (4) / su-lar-kı-zıl (4) = 8 hece, 4+4 duraklı.'),
  ('Türk halk şiirinde en sık kullanılan hece kalıpları hangileridir?', '7\'li ve 11\'li', ['5\'li ve 9\'lu', '10\'lu ve 13\'lü', '6\'lı ve 12\'li'], 'Halk şiirinde mâni ve türkülerde 7\'li, koşma ve destanlarda 11\'li kalıp en yaygın olanlardır.'),
  ('Bir şiirin bütün dizeleri 8 heceliyse ve bir dizede 9 hece varsa bu durum şiir hakkında ne gösterir?', 'O dizede ölçü aksaması vardır', ['Şiir serbest ölçüyle yazılmıştır', 'Şiir aruz ölçüsüyle yazılmıştır', 'Şiirde redif kullanılmamıştır'], 'Hece ölçüsünde tüm dizelerin hece sayısı eşit olmalıdır; farklı bir dize ölçü aksamasına işaret eder.'),
  ('Aruz ölçüsünde kısa okunması gereken bir hecenin ölçü gereği uzun okunmasına ne ad verilir?', 'İmale', ['Zihaf', 'Med', 'Ulama'], 'İmale, açık (kısa) bir hecenin vezin gereği uzatılarak kapalı gibi okunmasıdır ve çoğunlukla Türkçe sözcüklerde kusur sayılır.'),
  ('Bir aruz beytinde, vezin uzun bir hece gerektirirken o yerdeki kapalı hecenin kısa okunmak zorunda kalınması hangi terimle karşılanır?', 'Zihaf', ['İmale', 'Med', 'Durak'], 'Zihaf, kapalı (uzun) bir hecenin kısa okunmasıdır; imalenin tersidir.'),
  ('Aruz ölçüsünde açık hece ile kapalı hece nasıl tanımlanır?', 'Açık hece ünlüyle, kapalı hece ünsüzle biter', ['Açık hece ünsüzle, kapalı hece ünlüyle biter', 'Açık hece tek harfli, kapalı hece en az dört harflidir', 'Açık hece kalın ünlülü, kapalı hece ince ünlülüdür'], 'Aruzda ünlüyle biten heceler açık (kısa), ünsüzle ya da uzun ünlüyle biten heceler kapalı (uzun) sayılır.'),
  ('Serbest ölçüyle yazılmış bir şiirde ahenk daha çok hangi yollarla sağlanır?', 'Ses tekrarları, iç ritim ve vurgu', ['Uzun ve kısa hecelerin sabit sıralanması', 'Her dizenin eşit hece sayısında tutulması', 'Aruz kalıplarının dizeler arasında değiştirilmesi'], 'Serbest şiir sabit bir ölçüye bağlı olmadığından ahengi aliterasyon, asonans, tekrir ve iç ritimle kurar.'),
  ('\'Serbest şiir kafiyesiz olmak zorundadır.\' yargısı için aşağıdakilerden hangisi söylenebilir?', 'Yanlıştır; kafiye kullanılabilir ama zorunlu değildir', ['Doğrudur; serbest şiirde kafiye kullanımı kural gereği yasaktır', 'Doğrudur; kafiye yalnızca aruzla yazılan şiirde bulunur', 'Yanlıştır; serbest şiirde her dize mutlaka kafiyelidir'], 'Serbest şiir ölçü ve kafiye zorunluluğundan kurtulmuştur; şair dilerse kafiye ve redif kullanabilir.'),
  ('Aşağıdaki dize gruplarından hangisi serbest ölçüyle yazılmış bir şiire aittir?', 'Gece / ve ben uzun bir sokağın sonunda / bekledim', ['Sabah oldu kuşlar öttü / Pınar başı serin yeşil', 'Akşam iner köy yoluna / Çoban döner sürüsüyle', 'Dağlar başı duman olur / Sular yine akar durur'], 'İlk seçenekteki dizelerin hece sayıları birbirinden çok farklıdır. Diğer seçeneklerde her dize 8 hecelidir.'),
  ('\'taş\' ve \'kuş\' sözcüklerinin dize sonlarında kullanılmasıyla oluşan kafiye türü hangisidir?', 'Yarım kafiye', ['Tam kafiye', 'Zengin kafiye', 'Cinaslı kafiye'], 'Bu iki sözcükte yalnızca \'ş\' sesi ortaktır. Tek ses benzerliğine yarım kafiye denir.'),
  ('\'taş\' ve \'baş\' sözcükleri dize sonunda kafiyelendiğinde hangi kafiye türü oluşur?', 'Tam kafiye', ['Yarım kafiye', 'Zengin kafiye', 'Cinaslı kafiye'], 'İki sözcükte \'aş\' sesleri, yani bir ünlü ve bir ünsüz ortaktır; iki ses benzerliği tam kafiyedir.'),
  ('\'kara\' ve \'yara\' sözcükleri arasındaki ses benzerliği hangi kafiye türüne örnektir?', 'Zengin kafiye', ['Yarım kafiye', 'Tam kafiye', 'Cinaslı kafiye'], 'Ortak sesler \'ara\' olmak üzere üç sestir. Üç ya da daha fazla ses benzerliği zengin kafiyedir.'),
  ('Kafiye ile redif arasındaki temel fark nedir?', 'Redifte görev aynıdır, kafiyede görev ya da anlam farklıdır', ['Kafiye yalnızca dize başlarında, redif dize sonlarında bulunur', 'Redif yalnızca serbest şiirde, kafiye yalnız hece ölçüsünde görülür', 'Kafiye sözcük tekrarıdır, redif ise anlam tekrarıdır'], 'Redif, dize sonlarında görev ve anlamca aynı olan ek, sözcük ya da sözcük gruplarının tekrarıdır; kafiyede benzerlik görevce farklı seslerdedir.'),
  ('aaab / cccb biçimindeki kafiye düzenine ne ad verilir?', 'Düz kafiye', ['Çapraz kafiye', 'Sarma kafiye', 'Örüşük kafiye'], 'İlk üç dizenin kendi arasında, son dizenin diğer dörtlüklerin son dizeleriyle kafiyelendiği düzen düz kafiyedir.'),
  ('aba / bcb / cdc biçiminde, her üçlüğün orta dizesinin bir sonraki üçlüğün dış dizeleriyle kafiyelendiği düzene ne ad verilir?', 'Örüşük kafiye', ['Sarma (kucaklayan) kafiye', 'Düz kafiye', 'Çapraz kafiye'], 'Üçlükleri zincir gibi birbirine bağlayan bu düzen örüşük kafiyedir ve terzarimada kullanılır.'),
  ('Bir dörtlüğün dize sonları şöyledir: \'deniz / gece / sessiz / hece\'. Bu dörtlüğün kafiye şeması hangisidir?', 'abab', ['aabb', 'abba', 'aaab'], '\'deniz-sessiz\' (1 ve 3) ile \'gece-hece\' (2 ve 4) kafiyelidir; bu çapraz kafiyedir.'),
  ('Tiyatro eserlerinin manzum olarak yazılmasıyla ortaya çıkan, karşılıklı konuşmaya ve sahnelemeye dayanan şiir türü hangisidir?', 'Dramatik şiir', ['Lirik (duygusal) şiir', 'Pastoral şiir', 'Didaktik şiir'], 'Manzum tiyatro eserleri, yani trajedi ve komedilerin şiir biçiminde yazılanları dramatik şiir türündedir.'),
  ('Aşağıdaki şiir tanıtımlarından hangisi didaktik şiire aittir?', 'Gençlere çalışkanlığı öğütleyen bir manzume', ['Şairin sevgilisinden ayrılışının acısını anlattığı şiir', 'Bir köyde koyun güden çobanların akşamını anlatan şiir', 'Bir savaşta düşmanı yenen kahramanı anlatan şiir'], 'Öğüt verme amacı taşıyan ilk seçenek didaktiktir. Diğerleri sırasıyla lirik, pastoral ve epik şiir örnekleridir.'),
  ('Batı edebiyatında ölen birinin ardından yazılan, acı ve hüznü dile getiren lirik şiire ne ad verilir?', 'Eleji', ['Od', 'Satir', 'İdil'], 'Eleji (ağıt), ölüm ve kayıp karşısındaki acıyı dile getiren lirik şiir türüdür.'),
  ('Üçlüklerden oluşan, aba bcb cdc biçiminde kafiyelenen ve sonunda tek bir dizeyle biten nazım biçimine ne ad verilir?', 'Terzarima', ['Sone', 'Haiku', 'Balad'], 'Terzarima İtalyan kaynaklı bir biçimdir; Dante\'nin İlahi Komedya\'sı bu biçimde yazılmıştır.'),
  ('\'Kara kara bakar dağlar, akar sular ağlar\' dizesinde \'a\' sesinin baskın biçimde tekrarlanması hangi ahenk unsuruna örnektir?', 'Asonans', ['Aliterasyon', 'Redif', 'Cinas'], 'Aynı ünlünün yoğun tekrarı asonans adını alır.'),
  ('Bir sözcükte doğadaki bir sesin taklit edilmesine (şırıl şırıl, vızır vızır, çatır çatır gibi) dayanan ve şiirde ahenge katkı sağlayan yansıma kullanımının şiirdeki etkisi hangisidir?', 'Anlatılanı kulakta canlandırması', ['Dizeleri aruz kalıbına sokması', 'Kafiye türünü zengin kafiyeye çevirmesi', 'Şiirin temasını tümüyle değiştirmesi'], 'Yansıma sözcükler doğal sesleri taklit eder; okurun anlatılanı duyarak canlandırmasını sağlar.'),
  ('Serbest bir şiirde \'Bekledim / bekledim / bir ömür bekledim\' dizelerinde ahenk asıl olarak hangi yolla sağlanmıştır?', 'Sözcük tekrarı', ['Aruz kalıbı', 'Zengin kafiye', 'Asonans dışı bir ölçü kalıbı'], 'Aynı sözcüğün art arda yinelenmesi hem anlamı vurgular hem de ritmi oluşturur.'),
  ('Şiirde soyut bir duygunun ya da düşüncenin, okurun zihninde duyularla algılanabilir bir görüntüye dönüştürülmesine ne ad verilir?', 'İmge', ['Redif', 'Tema', 'Kafiye'], 'İmge, duyu organlarına seslenen zihinsel görüntüdür; şiire somutluk ve canlılık kazandırır.'),
  ('\'Ayrılık, kapının önünde unutulmuş soğuk bir çay bardağıydı.\' cümlesinde ayrılık duygusu nasıl anlatılmıştır?', 'Somut bir imgeyle', ['Bilimsel bir tanım yapılarak', 'Sayısal verilere başvurularak', 'Tarihsel bir olay hatırlatılarak'], 'Soyut bir duygu (ayrılık), görülebilir ve dokunulabilir somut bir görüntüyle anlatılmıştır; bu imge kullanımıdır.'),
  ('Şiir dilinin günlük konuşma dilinden ayrılan en belirgin özelliği nedir?', 'Sözcüklerin yoğun ve mecazlı kullanılması', ['Sözcüklerin yalnızca sözlükteki ilk anlamlarıyla kullanılması', 'Hiçbir zaman devrik cümle içermemesi', 'Her zaman uzun ve açıklayıcı cümleler kurulması'], 'Şiir dili yoğun, çağrışımlı ve mecazlıdır; sözcüklere yeni anlamlar yükler.'),
  ('Bir şiirin anlamının yalnız bir yoruma kapalı olmayıp okura göre farklı biçimlerde anlaşılabilmesi şiir dilinin hangi özelliğiyle ilgilidir?', 'Çok anlamlılık', ['Göndergesellik', 'Nesnellik ve tek anlamlılık', 'Kronolojiklik'], 'Şiir dili mecazlar ve imgeler aracılığıyla birden fazla anlama açık olabilir; bu çok anlamlılıktır.'),
  ('Bir şiirde belli bir sembolün (örneğin \'gemi\'nin ölümü ya da yolculuğu temsil etmesi) yinelenerek şiirin anlam katmanını oluşturması neye örnektir?', 'Sembol kullanımına', ['Durak kayması ve imaleye', 'Zihafa', 'Ulamaya'], 'Sembol, somut bir varlığın soyut bir kavramı temsil etmesidir ve şiire derinlik katar.'),
  ('Yalnızca benzeyen ve kendisine benzetilen unsurlarla, edat ve yön belirtilmeden yapılan güçlü benzetmeye ne ad verilir?', 'Teşbih-i beliğ', ['Açık istiare', 'Kapalı istiare', 'Mecazımürsel'], '\'Aslan asker\' ya da \'servi boy\' gibi yalnızca iki temel unsurun bulunduğu benzetmeler teşbih-i beliğdir.'),
  ('Aşağıdaki cümlelerin hangisinde teşbih-i beliğ vardır?', 'Taş yürekli adam kimseye acımadı.', ['Adamın yüreği taş gibi katıydı.', 'Adam kalbini bir taş kadar katılaştırmıştı.', 'Taş gibi sert bir yürekle konuştu.'], '\'Taş yürek\' sözünde yalnızca benzeyen (yürek) ve benzetilen (taş) vardır; edat ve yön söylenmemiştir.'),
  ('\'Gölün yüzeyi ayna gibiydi.\' ile \'Gölün yüzeyi ayna gibi parlaktı.\' cümleleri karşılaştırıldığında ikinci cümlede eklenen teşbih unsuru hangisidir?', 'Benzetme yönü', ['Benzetme edatı', 'Benzeyen', 'Kendisine benzetilen'], 'İkinci cümlede benzetmenin hangi bakımdan yapıldığı (\'parlak\') eklenmiştir; bu benzetme yönüdür.'),
  ('Yalnızca kendisine benzetilen unsurun söylendiği, benzeyenin ise söylenmediği istiareye ne ad verilir?', 'Açık istiare', ['Kapalı istiare', 'Teşbih-i beliğ', 'Temsilî istiare'], 'Açık istiarede benzetilen açıkça söylenir; benzeyen ise sezdirilir.'),
  ('\'Aslanlarımız cepheden zaferle döndü.\' cümlesinde hangi söz sanatı vardır?', 'Açık istiare', ['Kapalı istiare', 'Teşbih-i beliğ', 'Mübalağa'], 'Askerler (benzeyen) söylenmemiş, yalnızca \'aslan\' (kendisine benzetilen) söylenmiştir; bu açık istiaredir.'),
  ('\'Rüzgâr öfkeyle kükredi ve pencereleri yumrukladı.\' cümlesinde rüzgâr bir canavara benzetilmiş ama canavar söylenmemiştir. Bu söz sanatı hangisidir?', 'Kapalı istiare', ['Açık istiare', 'Teşbih-i beliğ', 'Telmih'], 'Benzeyen (rüzgâr) söylenmiş, benzetilenin (canavar) yalnızca özellikleri (kükreme, yumruklama) verilmiştir; bu kapalı istiaredir.'),
  ('Bir öğrenci \'Bu sabah sınıfa bir güneş girdi.\' cümlesinde güler yüzlü bir arkadaşının kastedildiğini fark ediyor. Öğrencinin tespit ettiği sanat hangisidir?', 'Açık istiare', ['Kapalı istiare', 'Teşbih-i beliğ', 'Hüsnütalil'], 'Arkadaş (benzeyen) söylenmemiş, yalnızca benzetilen \'güneş\' söylenmiştir; bu açık istiaredir.'),
  ('\'Kış gelince sobayı yaktık.\' cümlesinde aslında yakılan şeyin sobanın içindeki odun ya da kömür olması hangi ilgiye örnektir?', 'İç-dış ilgisi', ['Parça-bütün ilgisi', 'Sebep-sonuç ilgisi', 'Sanatçı-eser ilgisi'], 'Dıştaki (soba) söylenip içteki (yakıt) kastedilmiştir; bu iç-dış ilgisiyle yapılmış bir mecazımürseldir.'),
  ('\'Bu akşam Mozart dinledik.\' cümlesinde yapılan ad aktarmasının ilgisi nedir?', 'Sanatçı söylenip eserin kastedilmesi', ['Yer söylenip oradakilerin kastedilmesi', 'Bütün söylenip parçanın kastedilmesi', 'Dış söylenip içtekinin kastedilmesi'], 'Dinlenen besteci değil, onun eserleridir; sanatçı-eser ilgisiyle mecazımürsel yapılmıştır.'),
  ('Aşağıdaki cümlelerin hangisinde mecazımürsel yoktur?', 'Sabah kahvaltımı yaptım.', ['Bütün mahalle düğüne koştu.', 'Sabah iki bardak içip çıktı.', 'Dün akşam Çehov okudum.'], 'İlk cümlede sözcükler gerçek anlamdadır. Diğerlerinde yer-yerleşen, iç-dış ve sanatçı-eser ilgisiyle ad aktarması vardır.'),
  ('Bir sözün hem gerçek hem mecaz anlamını düşündürecek biçimde kullanılıp asıl olarak mecaz anlamının kastedilmesine ne ad verilir?', 'Kinaye', ['Mecazımürsel', 'Tevriye', 'Teşhis'], 'Kinayede sözün gerçek anlamı da düşünülebilir, ancak asıl kastedilen mecaz anlamıdır.'),
  ('\'O evin bacası çoktandır tütmüyor.\' cümlesinde kastedilen asıl anlam nedir?', 'Evde yoksulluk ya da sessizlik olduğu', ['Evin bacasının teknik bir arıza yaptığı', 'Evin yeni boyandığı', 'Evde misafir ağırlandığı'], 'Sözün gerçek anlamı (bacanın tütmemesi) düşünülebilir; ama asıl kastedilen, o evde yemek pişmediği, yoksulluk ya da issizlik olduğudur. Bu kinayedir.'),
  ('Aşağıdaki cümlelerin hangisinde kinaye vardır?', 'Bu iş için kolları sıvadık.', ['Bu sabah kollarımda ağrı vardı.', 'Gömleğimin kolları biraz uzundu.', 'Kolundaki saati bana gösterdi.'], '\'Kolları sıvamak\', gerçek anlamı da düşünülebilen ama \'bir işe kararlılıkla girişmek\' anlamında kullanılan kinayeli bir sözdür.'),
  ('\'Kırlangıç bana dönüp "Bahar geliyor, sabret!" dedi.\' cümlesinde aynı anda bulunan söz sanatları hangileridir?', 'Teşhis ve intak', ['Tezat ve mübalağa', 'Telmih ve irsalimesel', 'Cinas ve tevriye'], 'Kırlangıç konuşturulmuştur (intak); konuşan bir hayvan insan özelliği kazandığı için teşhis de vardır.'),
  ('Aşağıdaki dizelerin hangisinde intak vardır?', 'Rüzgâr \'Dön artık\' diye fısıldadı', ['Gece sessizce örttü bütün evleri', 'Söğüt dallarını suya uzatıp ağladı', 'Sabah, pencereme gülümseyerek geldi'], 'Yalnızca ilk dizede rüzgâr konuşturulmuştur. Diğerlerinde teşhis vardır ama konuşturma yoktur.'),
  ('Fabllarda ve çocuk edebiyatında teşhis ve intakın sık kullanılmasının temel nedeni nedir?', 'Anlatılanı canlı ve anlaşılır kılması', ['Metnin ölçüsünü aruza uydurması', 'Metni bilimsel bir kesinliğe kavuşturması', 'Olayların tarihini belirlemeyi kolaylaştırması'], 'Kişileştirme ve konuşturma, soyut dersleri somut kahramanlar aracılığıyla canlı ve anlaşılır biçimde sunar.'),
  ('Aşağıdaki dizelerin hangisinde tezat yoktur?', 'Sabah yeli eser bahçe yolunda', ['Ne zengin mutluydu ne de yoksul', 'Gece karanlık, gönlüm aydınlık', 'Ak saçlı başında kara bir sevda'], 'Diğer seçeneklerde zengin-yoksul, karanlık-aydınlık, ak-kara karşıtlıkları vardır. İlk dizede karşıt kavram yoktur.'),
  ('Tezat sanatı bir anlatıma en çok hangi etkiyi kazandırır?', 'Karşıtlık yoluyla anlamı belirginleştirir', ['Dizelere sabit ve düzenli bir ölçü kazandırır', 'Metne tarihsel bir gönderme ekler', 'Olayları kronolojik sıraya koyar'], 'Zıt kavramlar yan yana geldiğinde her biri diğerini daha görünür kılar; anlam keskinleşir.'),
  ('\'Öyle ağladı ki gözyaşları sokakları sel gibi bastı.\' cümlesinde hangi iki söz sanatı birlikte kullanılmıştır?', 'Mübalağa ve teşbih', ['Tezat ve telmih', 'Kinaye ve tevriye', 'İntak ve irsalimesel'], 'Gözyaşının sokakları basması abartmadır (mübalağa); \'sel gibi\' ifadesi de benzetmedir (teşbih).'),
  ('Günlük dilde \'Ölüyorum açlıktan!\', \'Ömrüm geçti seni beklerken!\' gibi sözlerin sık kullanılması mübalağanın hangi işlevini gösterir?', 'Duyguyu güçlü biçimde ifade etmeyi', ['Bilimsel bir gerçeği kanıtlamayı', 'Bir atasözünü hatırlatmayı', 'Sözcüklerin sesteşliğini vurgulamayı'], 'Abartı, konuşanın içinde bulunduğu duyguyu yoğun ve etkili biçimde aktarmasını sağlar.'),
  ('\'Bu parlayan senin gözlerin mi, yoksa gökyüzünden düşmüş iki yıldız mı?\' cümlesinde hangi sanat yapılmıştır?', 'Tecahülüarif', ['Hüsnütalil', 'Tezat', 'İrsalimesel'], 'Söyleyen kişi parlayanların göz olduğunu bilmektedir, ama bilmiyormuş gibi davranarak bir benzetmeyi soru biçiminde sunmuştur.'),
  ('Tecahülüarif sanatında en sık başvurulan anlatım biçimi hangisidir?', 'Soru cümlesi', ['Emir kipi', 'Sayısal veri', 'Tanık gösterme'], 'Bilmezlikten gelme çoğunlukla \'Bu ... mı, yoksa ... mı?\' gibi soru biçiminde yapılır; ancak soru zorunlu değildir.'),
  ('Aşağıdaki cümlelerin hangisinde tecahülüarif vardır?', 'Ay mı doğdu pencereme, yoksa sen mi gülümsedin?', ['Ay bu gece her zamankinden çok daha parlaktı.', 'Sen gülünce dünyam aydınlandı.', 'Pencereden ay ışığı süzülüyordu.'], 'İlk cümlede gülümseyenin sevgili olduğu bilindiği hâlde, bilmezlikten gelinerek aya benzetme yapılmıştır.'),
  ('\'Güneş, senin yüzünü kıskandığı için her akşam utanıp batıyor.\' cümlesinde hangi söz sanatı vardır?', 'Hüsnütalil', ['Tecahülüarif', 'Kinaye', 'Tezat'], 'Güneşin batmasının gerçek nedeni dünyanın dönüşüdür; bu olay kıskançlık ve utanç gibi şairane bir nedene bağlanmıştır.'),
  ('Aşağıdaki cümlelerden hangisi hüsnütalile örnek değildir?', 'Rüzgâr çıktığı için yapraklar dökülüyordu.', ['Yapraklar, sonbaharın hüznüne dayanamadığı için dökülüyordu.', 'Dere, denize kavuşma hasretiyle koşuyordu.', 'Kar, kirli şehri utandırmak için beyaz yağıyordu.'], 'İlk cümlede dökülme gerçek bir nedene bağlanmıştır. Diğerlerinde olaylar hayalî, şairane nedenlerle açıklanmıştır.'),
  ('Aşağıdaki sözcük gruplarından hangisi bir dizede kullanıldığında tenasüp oluşturmaz?', 'Siyah, beyaz', ['Kalem, kâğıt, mürekkep', 'Gemi, liman, dalga', 'Tarla, saban, ekin'], '\'Siyah-beyaz\' karşıt kavramlardır ve tezat oluşturur; diğerleri anlamca ilgili sözcüklerdir.'),
  ('\'Bu hediye bir Truva atı olabilir, dikkatli ol.\' cümlesinde yapılan telmihin anlamı nedir?', 'Masum görünenin tehlike gizleyebileceği', ['Hediyenin çok değerli olduğu', 'Hediyenin tarihî bir eser olduğu', 'Hediyenin hızlı ulaştırılması gerektiği'], 'Truva atı efsanesine göre Yunanlılar şehre hediye görünümündeki tahta atın içine gizlenerek girmiştir; telmih bu aldatıcılığı hatırlatır.'),
  ('Bir metinde telmihin anlaşılabilmesi okurdan öncelikle neyi bekler?', 'Gönderme yapılan olayı bilmesini', ['Aruz kalıplarını ve zihafları tanımasını', 'Metni sesli okumasını', 'Kafiye şemasını çıkarmasını'], 'Telmih kısa bir hatırlatma olduğundan, okur ancak gönderme yapılan hikâyeyi biliyorsa anlamı kavrar.'),
  ('\'Gurbette kimse sormaz hâlimi, el elin eşeğini türkü çağırarak arar.\' dizesinde hangi söz sanatı vardır?', 'İrsalimesel', ['Tezat', 'Telmih', 'Tevriye'], 'Şair, gurbette kimsenin ilgilenmediği düşüncesini \'El elin eşeğini türkü çağırarak arar\' atasözüyle desteklemiştir.'),
  ('\'Gül yüzlüm, bir kez de gül, karanlık gönlüm aydınlansın.\' cümlesinde \'gül\' sözcükleriyle hangi sanat yapılmıştır?', 'Cinas', ['Tezat', 'Telmih', 'Mübalağa'], 'İlk \'gül\' çiçek anlamında, ikinci \'gül\' gülmek eyleminin emir biçimidir; sesteş sözcüklerin kullanılması cinastır.'),
  ('Bir sözcüğün yakın ve uzak iki anlamı olup asıl olarak uzak anlamının kastedilmesine ne ad verilir?', 'Tevriye', ['Cinas', 'Kinaye', 'İstiare'], 'Tevriye (iki anlamlılık), birden çok anlamı olan bir sözcüğü uzak anlamını kastederek kullanmaktır.'),
  ('\'Ey vatan! Kim unutur senin uğrunda dökülen kanı?\' cümlesinde hangi iki sanat birlikte kullanılmıştır?', 'Nida ve istifham', ['Tezat ve telmih', 'Cinas ve tekrir', 'Kinaye ve tevriye'], '\'Ey vatan!\' bir seslenme (nida), \'Kim unutur...?\' ise yanıt beklenmeyen bir sorudur (istifham).'),
  ('Bir şiirde aynı dizenin her bent sonunda tekrarlanması (nakarat) hangi sanatın geniş ölçekte kullanımı olarak görülebilir?', 'Tekrir', ['Telmih', 'Tezat', 'Mecazımürsel'], 'Nakarat, belirli dizelerin düzenli aralıklarla yinelenmesidir; bu da bir tür tekrirdir.'),
  ('Bir kişiyi ya da durumu, söylenenin tam tersini kastederek alaylı ve iğneleyici biçimde anlatmaya ne ad verilir?', 'Tariz', ['Tezat', 'Tenasüp', 'Telmih'], 'Tariz (iğnelemeli söz), sözü tersini kastederek, alay yoluyla söylemektir.'),
  ('\'Bazıları kitap okumanın artık gereksiz olduğunu, her bilginin internette bulunduğunu söylüyor. Oysa bilgiye ulaşmak ile onu anlamlandırmak aynı şey değildir.\' parçasının anlatım biçimi hangisidir?', 'Tartışmacı', ['Öyküleyici', 'Betimleyici', 'Açıklayıcı'], 'Önce karşıt görüş verilmiş (\'Bazıları ... söylüyor\'), sonra \'Oysa\' ile çürütülmüştür; bu tartışmacı anlatımdır.'),
  ('Betimlemede yazarın kendi duygu ve izlenimlerini katarak yaptığı tasvire ne ad verilir?', 'İzlenimsel (sanatsal) betimleme', ['Açıklayıcı (teknik) betimleme', 'Tartışmacı betimleme', 'Kronolojik betimleme'], 'Sanatsal betimlemede yazarın kişisel izlenimleri öne çıkar; açıklayıcı betimleme ise nesnel ve bilgi vericidir.'),
  ('\'Kalenin surları 12 metre yüksekliğinde ve yaklaşık 3 metre kalınlığındadır; dört ana kapısı vardır.\' cümlesindeki betimleme türü hangisidir?', 'Açıklayıcı betimleme', ['Sanatsal (izlenimsel) betimleme', 'İzlenimci betimleme', 'Öyküleyici betimleme'], 'Ölçülere dayanan, kişisel izlenim içermeyen bu tasvir, bilgi vermeye yönelik açıklayıcı (nesnel) betimlemedir.'),
  ('Bir betimlemede kişinin yalnızca dış görünüşüyle değil, huyu ve karakteriyle de tanıtılmasına ne ad verilir?', 'Portre', ['Röportaj', 'Kronoloji', 'Monolog'], 'Portre, bir kişiyi fiziksel ve ruhsal özellikleriyle birlikte tanıtan betimlemedir.'),
  ('Hangisinde betimleme ile öyküleme bir arada kullanılmıştır?', 'Sisli sokaklardan geçip, kırık camlı eski eve yaklaştı.', ['Fotosentez yeşil bitkilerde gerçekleşir.', 'Kimileri yalnızlığı sever; ama insan sosyal bir varlıktır.', 'Dağın eteği mor çiçeklerle kaplıydı.'], 'İlk cümlede bir hareket (geçip yaklaşma) ve mekânın nitelikleri (sisli, kırık camlı, eski) birlikte verilmiştir.'),
  ('Aşağıdakilerden hangisi tartışmacı anlatımda sık görülen bir ifadedir?', '\'Kimileri böyle düşünüyor, ama...\'', ['\'Bir varmış, bir yokmuş...\'', '\'Uzun, ince, beyaz bir kuleydi...\'', '\'Sabah oldu, kalktı, yola çıktı...\''], 'Karşıt görüşü anıp ardından çürütmeye geçmek tartışmacı anlatımın tipik yapısıdır. Diğerleri masal, betimleme ve öyküleme kalıplarıdır.'),
  ('Tanık gösterme yolunun bir metne kazandırdığı en temel nitelik hangisidir?', 'İnandırıcılığı artırması', ['Metni masalsı bir havaya sokması', 'Metne ölçü ve kafiye kazandırması', 'Olayların kronolojisini belirlemesi'], 'Alanında yetkin bir kişinin sözü, savunulan düşünceye güven ve inandırıcılık kazandırır.'),
  ('\'Araştırmaya göre öğrencilerin yüzde altmışı günde bir saatten az kitap okuyor.\' cümlesinin bir tartışma metnindeki işlevi nedir?', 'Savı nesnel bir veriyle desteklemek', ['Okuru güldürmek', 'Bir olayı kronolojik olarak anlatmak', 'Bir kişiyi portre biçiminde tanıtmak'], 'Sayısal veri, savı ölçülebilir bir kanıtla güçlendirerek nesnel bir dayanak sağlar.'),
  ('Bir yazarın, \'Yunus Emre\'nin dediği gibi "Sevelim, sevilelim"\' ifadesiyle düşüncesini desteklemesi hangi yola örnektir?', 'Tanık gösterme', ['Tanımlama', 'Karşılaştırma', 'Sayısal veri'], 'Tanınmış bir kişinin sözü düşünceyi desteklemek için kullanılmıştır.'),
  ('Bir yazar \'Dil, bir milletin hafızasıdır.\' cümlesini kuruyor. Bu cümlede soyut bir kavram hangi yolla anlatılmıştır?', 'Benzetme', ['Sayısal veri', 'Tanık gösterme', 'Karşılaştırma'], 'Dil, edat kullanılmadan hafızaya benzetilmiştir; bu benzetme yoluyla soyut kavramın açıklanmasıdır.'),
  ('\'Elif kapıyı açtığında içinden, bu kez ağlamayacağım, diye geçirdi. Oysa annesinin de aynı korkuyla beklediğinden habersizdi.\' parçasındaki bakış açısı hangisidir?', 'İlahi', ['Kahraman', 'Gözlemci', 'Birinci kişi'], 'Anlatıcı hem Elif\'in hem annesinin iç dünyasını bilmektedir; bu, her şeyi bilen ilahi bakış açısıdır.'),
  ('\'Adam masaya oturdu, çayını yudumladı ve gazetesini açtı. Garson yanına gelip bir şey söyledi; adam başını salladı.\' parçasında hangi bakış açısı kullanılmıştır?', 'Gözlemci', ['İlahi', 'Kahraman', 'Bilinç akışı'], 'Anlatıcı yalnız dışarıdan görüleni aktarmakta, adamın ne düşündüğünü ya da garsonun ne dediğini bilmemektedir.'),
  ('Kahraman bakış açısının en önemli sınırlılığı hangisidir?', 'Başkalarının iç dünyasını bilememesi', ['Olayların hiç anlatılamaması', 'Metnin mutlaka şiir biçiminde olması', 'Anlatıcının kendisini tanıtamaması'], 'Kahraman anlatıcı yalnızca kendi düşünce ve duygularını bilir; diğer kişiler hakkında tahminde bulunabilir ama kesin bilgi veremez.'),
  ('Bir romanda olayların birden çok kişinin ağzından, her bölümde farklı bir anlatıcıyla aktarılmasına ne ad verilir?', 'Çoğul anlatıcı', ['İlahi anlatıcı', 'Gözlemci anlatıcı', 'Tek kişilik anlatım'], 'Çoğul anlatıcılı romanlarda aynı olaylar farklı kişilerin bakışından aktarılır; böylece tek bir doğru yerine farklı bakışlar ortaya çıkar.'),
  ('Bir öyküde anlatıcı \'sen\' diye seslenerek kahramanı anlatıyorsa (\'Sabah kalkıyorsun, aynaya bakıyorsun...\') bu anlatımda kullanılan kişi hangisidir?', 'İkinci tekil kişi', ['Birinci tekil kişi', 'Üçüncü tekil kişi', 'Birinci çoğul kişi'], '\'Sen\' anlatımı ikinci tekil kişiyle yapılan, okuru kahramanla özdeşleştirmeye yönelik az kullanılan bir anlatım biçimidir.'),
  ('Aşağıdaki cümlelerden hangisi gözlemci bakış açısıyla yazılmış bir metinde yer alamaz?', 'Kadın, kocasının yalan söylediğini düşünüyordu.', ['Kadın pencereye yaklaştı ve perdeyi araladı.', 'Kocası kapıda durup ceketini çıkardı.', 'Saat duvarda gece yarısını gösteriyordu.'], 'Gözlemci anlatıcı kişilerin ne düşündüğünü bilemez; ilk seçenekte kadının düşüncesi aktarıldığı için bu bakışla bağdaşmaz.'),
  ('Kahramanın kendi kendine konuşması biçiminde, iç sesinin düzenli cümlelerle verildiği anlatım tekniğine ne ad verilir?', 'İç monolog', ['Bilinç akışı', 'Diyalog', 'Montaj'], 'İç monologda kahraman kendi kendine konuşur; bilinç akışına göre daha düzenli ve mantıklı bir yapı vardır.'),
  ('Bir romanda belirli bir sözün, imgenin ya da motifin eser boyunca tekrar tekrar karşımıza çıkarak anlamı pekiştirmesine ne ad verilir?', 'Leitmotiv', ['Montaj', 'İç monolog', 'Geriye dönüş'], 'Leitmotiv (ana motif), eserde yinelenen ve bir duygu ya da düşünceyi simgeleyen öğedir.'),
  ('Bir öyküde gazete haberi, şarkı sözü, reklam metni ya da belge gibi farklı türden metinlerin anlatıya yerleştirilmesine ne ad verilir?', 'Montaj', ['Leitmotiv', 'Bilinç akışı', 'Geriye dönüş'], 'Montaj, kurmaca anlatıya dışarıdan alınmış gerçek ya da farklı türde metin parçalarının eklenmesidir.'),
  ('Ünlü bir eserin üslubunu ya da konusunu abartarak, güldürmek ya da eleştirmek amacıyla taklit eden yazıya ne ad verilir?', 'Parodi', ['Pastiş', 'Portre', 'Röportaj'], 'Parodi, bir eseri ya da üslubu alaycı bir yaklaşımla taklit eder; pastiş ise alay amacı taşımayan öykünmedir.'),
  ('Bir öyküde aşağıdaki cümle yer alıyor: \'yağmur yine yağmur annemin sesi mutfakta kaynayan su ve o mektup hiç gelmeyen mektup neden\'. Bu cümledeki teknik hangisidir?', 'Bilinç akışı', ['İç monolog', 'Gözlemci anlatım', 'Montaj'], 'Noktalama yoktur, çağrışımlar mantık sırası gözetilmeden birbirine bağlanmıştır; bu bilinç akışıdır.'),
  ('Diyalogların bir öyküde fazla kullanılması anlatıya en çok hangi özelliği kazandırır?', 'Canlılık ve sahne etkisi', ['Bilimsel ve nesnel bir kesinlik', 'Ölçülü bir ahenk', 'Kesin bir kronoloji'], 'Karşılıklı konuşmalar okura olayı doğrudan izliyormuş gibi hissettirir ve anlatıya tiyatro sahnesi canlılığı katar.'),
  ('Bir anlatıda gerilimin en yüksek noktaya ulaştığı, olayların bir dönüm noktasına geldiği ana ne ad verilir?', 'Doruk noktası', ['Serim', 'Başlangıç durumu', 'Son söz'], 'Doruk noktası (klimaks), çatışmanın en yoğun yaşandığı ve çözüme geçilen andır.'),
  ('Bir romanda \'Aradan on yıl geçti.\' cümlesiyle bir anda sonraki döneme geçilmesi zamanın hangi biçimde kullanıldığını gösterir?', 'Zaman atlaması', ['Geriye dönüş', 'Bilinç akışı', 'Doruk noktası'], 'Uzun bir sürenin tek cümleyle geçilmesi anlatıda zaman atlaması ya da özetlemedir.'),
  ('Bir öyküde dar, karanlık ve nemli bir bodrum katının ayrıntılı betimlenmesi kahramanın bunalımlı ruh hâliyle paralellik gösteriyor. Bu durum için hangisi söylenebilir?', 'Mekân kişinin iç dünyasını yansıtmaktadır', ['Mekân öyküde hiçbir işlev taşımamaktadır', 'Öykü masal türüne aittir', 'Öykü kahraman bakış açısıyla yazılamaz'], 'Mekânın karanlık ve daraltıcı nitelikleri kahramanın ruh hâlini simgelemektedir; mekân ile kişi arasında anlamlı bir ilişki kurulmuştur.'),
  ('Bir öyküde başlangıçtaki durumun, sonunda hemen hemen aynı biçimde yeniden ortaya çıkmasıyla oluşan yapıya ne ad verilir?', 'Döngüsel yapı', ['Açık uçlu yapı', 'Paralel kurgu', 'Doğrusal yapı'], 'Döngüsel (dairesel) yapıda anlatı başladığı yere ya da duruma geri dönerek tamamlanır.'),
  ('Bir romanda asıl olay dizisinin yanında ona bağlı ikinci bir olay dizisi daha işleniyorsa bu ikinci diziye ne ad verilir?', 'Yan olay örgüsü', ['Ana tema', 'Leitmotiv', 'Doruk noktası'], 'Ana olay örgüsünü destekleyen ya da onunla iç içe gelişen ikincil olay dizisi yan olay örgüsüdür.'),
  ('Telefonda \'Alo, beni duyabiliyor musun?\' denmesi dilin hangi işlevine örnektir?', 'Kanalı kontrol', ['Şiirsel', 'Heyecana bağlı', 'Dil ötesi'], 'İletişim kanalının açık olup olmadığını denetlemeye yönelik sözler kanalı kontrol işlevindedir.'),
  ('\'"Kitap" sözcüğü Arapça kökenlidir ve iki hecelidir.\' cümlesinde dil hangi işlevde kullanılmıştır?', 'Dil ötesi işlev', ['Kanalı kontrol işlevi', 'Heyecana bağlı işlev', 'Şiirsel işlev'], 'Dilin dil hakkında bilgi vermek için kullanılması dil ötesi (üst dil) işlevdir; dil bilgisi kitapları ve sözlükler bu işlevi kullanır.'),
  ('Bir reklam metninde \'Sen de hemen dene, farkı hisset!\' ifadesinin kullanılmasının dil işlevi bakımından amacı nedir?', 'Alıcıyı bir eyleme yöneltmek', ['Dil hakkında bilgi vermek', 'İletişim kanalını denetlemek', 'Yalnızca bilimsel bilgi aktarmak'], 'Emir kipi ve doğrudan seslenme, alıcıyı harekete geçirme işlevini gösterir; reklamlarda bu işlev baskındır.'),
  ('Sanatsal metinlerle öğretici metinler karşılaştırıldığında aşağıdakilerden hangisi öğretici metinlerin özelliğidir?', 'Sözcüklerin gerçek anlamıyla kullanılması', ['Kurmaca bir dünya oluşturulması', 'Çok anlamlılığın amaçlanması', 'Dilin şiirsel işlevinin baskın olması'], 'Öğretici metinler bilgi vermeyi amaçladığından dil açık, nesnel ve gerçek anlamlıdır; diğer seçenekler sanatsal metinlere aittir.'),
  ('Bir romanda gerçek bir şehrin sokak adları ve tarihî olaylar geçiyorsa bu roman için ne söylenebilir?', 'Gerçeklikten yararlanan bir kurmacadır', ['Bir tarih belgesi niteliği taşır', 'Kurmaca olma özelliğini yitirir', 'Biyografi türüne girer'], 'Gerçek mekân ve olayların kullanılması romanı belgeye dönüştürmez; bunlar kurmaca dünyanın inandırıcılığına hizmet eder.'),
  ('Kurmaca metinler ile gerçeğe dayalı metinler (biyografi, anı, gezi yazısı) arasındaki temel fark hangisidir?', 'Kurmacada yaşanmamış olaylar anlatılabilir', ['Kurmaca metinlerde hiç mekân bulunmaz', 'Gerçeğe dayalı metinlerde anlatıcı olmaz', 'Kurmaca metinler yalnızca şiir biçimindedir'], 'Kurmacada olaylar yaşanmış olmak zorunda değildir; anı ve biyografi gibi türler ise gerçek olaylara dayanmak zorundadır.'),
  ('Bir öyküde okurun anlatılanları gerçekmiş gibi kabul etmesini sağlayan niteliğe ne ad verilir?', 'İnandırıcılık', ['Ölçü birliği', 'Kafiye düzeni', 'Redif kullanımı'], 'Kurmaca olaylar gerçekte yaşanmamış olsa da mantıklı ve tutarlı kurulduğunda okur onları inandırıcı bulur.'),
  ('Bir yazarın yaşadığı bir olayı, adları ve bazı ayrıntıları değiştirerek bir öyküye dönüştürmesi için aşağıdakilerden hangisi doğrudur?', 'Metin kurmacadır; olay yalnız kaynaktır', ['Metin anı türüne girer', 'Metin biyografi olarak sınıflandırılır', 'Metin bir gezi yazısıdır'], 'Yazar gerçek olayı kurguya dönüştürmüş, ayrıntıları değiştirmiştir; bu durumda metin kurmacadır.'),
  ('Bir okur, bir romandaki kahramanı gerçekten yaşamış biri sanıp romanı tarih kitabı gibi okuyor. Bu okurun yaptığı hata nedir?', 'Kurmaca ile gerçekliği birbirine karıştırması', ['Romanın ölçüsünü yanlış belirlemesi', 'Romandaki redifleri atlaması', 'Romanın türünü fabl sanması'], 'Roman gerçeklikten beslense de kurmacadır; kahramanlar ve olaylar belge değeri taşımaz.'),
  ('\'Bir ayrılık acısı ki ne dağlar taşır, ne denizler.\' cümlesinde öne çıkan söz sanatı hangisidir?', 'Mübalağa', ['Tenasüp ve telmih', 'Cinas ve tevriye', 'İntak ve tecrit'], 'Acının dağların ve denizlerin bile taşıyamayacağı kadar büyük gösterilmesi abartmadır.'),
  ('Aşağıdaki cümlelerin hangisinde mecazımürsel vardır?', 'Bütün kasaba onu karşılamaya çıktı.', ['Kasabanın çevresi yemyeşil bağlarla kaplıydı.', 'Kasabaya akşamüstü vardık.', 'Kasaba ile şehir arasında bir köprü vardı.'], 'Karşılamaya çıkan kasabanın kendisi değil, kasaba halkıdır; yer söylenip yerleşenler kastedilmiştir.'),
  ('\'O, güneşi bile kıskandıran bir gülüşe sahipti.\' cümlesinde aşağıdaki sanatlardan hangileri bir arada bulunur?', 'Mübalağa ve teşhis', ['Tezat ve tenasüp', 'Cinas ve telmih', 'İrsalimesel ve tecrit'], 'Gülüşün güneşi kıskandırması abartmadır; güneşe kıskanma duygusu verilmesi ise kişileştirmedir.'),
  ('\'Gün doğmadan neler doğar\' diyerek umudunu koruyan şair, bu söz sanatıyla ne yapmıştır?', 'Düşüncesini bir atasözüyle desteklemiştir', ['Bilmezlikten gelerek soru sormuştur', 'Karşıt kavramları bir arada kullanmıştır', 'Bilinen bir efsaneye gönderme yapmıştır'], 'Şair düşüncesini kanıtlamak için atasözüne başvurmuştur; bu irsalimeseldir.'),
  ('Bir öğrenci \'Kerem gibi yandım\' dizesinde yalnızca teşbih bulunduğunu söylüyor. Öğrencinin gözden kaçırdığı sanat hangisidir?', 'Telmih', ['Tezat', 'Tecrit', 'Cinas'], '\'Gibi\' ile teşbih vardır; ama Kerem ile Aslı hikâyesinde Kerem\'in yanarak ölmesine gönderme yapıldığı için telmih de bulunur.'),
  ('Tiyatro oyunlarının başında oyunun konusu ya da amacı hakkında seyirciye bilgi veren giriş bölümüne ne ad verilir?', 'Prolog', ['Epilog', 'Apart', 'Tirad'], 'Prolog, oyunun başında yer alan ve seyirciyi oyuna hazırlayan giriş konuşmasıdır; sondaki kapanış bölümü ise epilogdur.'),
  ('Duygusal etkiyi artırmak için olayların abartıldığı, iyilerle kötülerin kesin çizgilerle ayrıldığı ve genellikle müzikle desteklenen tiyatro türüne ne ad verilir?', 'Melodram', ['Trajedi', 'Komedi', 'Pandomim'], 'Melodram, abartılı duygusallık ve kesin iyi-kötü ayrımıyla seyirciyi duygulandırmayı amaçlar.'),
  ('Şarkılı, danslı ve hafif güldürüye dayanan, çoğu zaman karışık aşk entrikalarını konu alan sahne türüne ne ad verilir?', 'Vodvil', ['Trajedi', 'Pandomim', 'Melodram'], 'Vodvil, müzik ve şarkılarla süslenmiş hafif bir komedi türüdür.'),
  ('Bir tiyatro metni ile bir öykü metni karşılaştırıldığında, tiyatro metninde öyküdekinden farklı olarak hangisi mutlaka bulunur?', 'Kişilerin konuşmalarının adlarıyla birlikte verilmesi', ['Olayların bir anlatıcı tarafından aktarılması', 'Kişilerin iç dünyasının uzun betimlemelerle anlatılması', 'Olay örgüsünün tamamen özetlenmesi'], 'Tiyatro metinleri diyaloglar üzerine kurulur; her replik konuşan kişinin adıyla verilir. Anlatıcı yerine sahne yönergeleri bulunur.'),
  ('Tiyatroda oyunun sonunda yer alan, oyunun anlamını toparlayan ya da seyirciye veda eden kapanış bölümüne ne ad verilir?', 'Epilog', ['Prolog', 'Apart', 'Replik'], 'Epilog, eserin sonunda yer alan kapanış bölümüdür.'),
  ('Evrenin, insanın ve doğa olaylarının yaratılışını tanrılar ve doğaüstü varlıklar aracılığıyla açıklayan kutsal sayılmış anlatılara ne ad verilir?', 'Mit', ['Fıkra', 'Anekdot', 'Fabl'], 'Mitler (söylenceler), ilkel toplumların evreni ve doğayı açıklama çabasından doğan, kutsal kabul edilmiş anlatılardır.'),
  ('Ünlü bir kişinin hayatından alınmış, ilginç ve çoğu zaman düşündürücü kısa bir olayın anlatılmasına ne ad verilir?', 'Anekdot', ['Röportaj', 'Biyografi', 'Destan'], 'Anekdot, bir kişinin hayatından alınmış kısa ve ilgi çekici olaydır; konuşma ve yazılarda düşünceyi canlandırmak için kullanılır.'),
  ('Ünlü bir kişiye ait, derin bir düşünceyi kısa ve etkili biçimde dile getiren söze ne ad verilir?', 'Vecize (özdeyiş)', ['Atasözü (anonim)', 'Tekerleme (masal girişi)', 'Bilmece (soru-cevap)'], 'Vecize ya da özdeyiş, söyleyeni belli olan özlü sözdür; atasözlerinin ise söyleyeni belli değildir.'),
  ('Ölçü ve kafiye kullanmadan, şiirsel bir dil ve yoğun duygu ile düz yazı biçiminde yazılan metinlere ne ad verilir?', 'Mensur şiir', ['Manzum hikâye', 'Serbest ölçülü koşma', 'Lirik destan'], 'Mensur şiir (düz yazı şiir), nesir biçiminde yazılmış ama şiirin duygu yoğunluğunu ve imge dilini taşıyan metindir.'),
  ('Bir olayın ölçülü ve kafiyeli dizelerle, kişi, yer ve zaman unsurları kullanılarak anlatıldığı türe ne ad verilir?', 'Manzum hikâye', ['Mensur şiir', 'Deneme', 'Fıkra'], 'Manzum hikâye, öykü unsurlarını şiir biçiminde sunan türdür.'),
  ('\'Mutluluk nedir diye sorarsanız, size kesin bir tanım veremem. Bana kalırsa mutluluk, bir sabah pencereden süzülen ışıkta gizlidir belki de.\' parçasının türü hangisidir?', 'Deneme', ['Makale', 'Haber', 'Biyografi'], 'Yazar kesin yargıdan kaçınarak kişisel düşüncelerini samimi bir dille paylaşmaktadır.'),
  ('\'Araştırmalar, düzenli kitap okuyan çocukların söz varlığının okumayanlara göre belirgin biçimde geniş olduğunu göstermektedir. Bu nedenle okuma alışkanlığı erken yaşta kazandırılmalıdır.\' parçası hangi türe aittir?', 'Makale', ['Deneme', 'Anı', 'Sohbet'], 'Bir tez veriye dayanılarak savunulmuştur; bu makalenin özelliğidir.'),
  ('\'Dün akşam belediye otobüslerinin saatleri yine değişti. Durakta bekleyen yurttaşa kimse bir açıklama yapmadı. Bu kentte bekleyen hep vatandaş mı olacak?\' parçasının ait olabileceği tür hangisidir?', 'Fıkra', ['Hikâye', 'Anı', 'Biyografi'], 'Güncel bir konuda yazarın kişisel tepkisini kısa ve iğneleyici biçimde dile getirmesi gazete fıkrasının (köşe yazısının) özelliğidir.'),
  ('\'1881\'de doğdu. İlköğrenimini memleketinde tamamladıktan sonra İstanbul\'a gitti; burada hukuk okudu ve gazetecilik yaptı.\' parçası hangi türe örnektir?', 'Biyografi', ['Otobiyografi', 'Günlük', 'Anı'], 'Üçüncü kişi ağzıyla bir başkasının hayatının kronolojik olarak anlatılması biyografidir.'),
  ('\'— Sizce genç yazarlar en çok neye dikkat etmeli? — Okumaya. Yazmadan önce bol bol okumalılar.\' biçiminde süren bir metin hangi türe aittir?', 'Mülakat', ['Röportaj', 'Deneme', 'Tiyatro'], 'Tanınmış bir kişiyle yapılan soru-cevap biçimindeki görüşme mülakattır.'),
  ('\'Siz hiç bir çocuğun gözlerinde sabahı gördünüz mü, değerli okurlarım? Ben gördüm; hem de dün, otobüste.\' parçasının türü hangisidir?', 'Sohbet', ['Makale', 'Haber', 'Biyografi'], 'Okura doğrudan seslenme ve onunla konuşuyormuş gibi bir hava yaratma sohbet türüne özgüdür.'),
  ('\'Yaprak döker / bahçemizde / çınarlar\' dizesinin ölçü ve durak yapısı hangisidir?', '11\'li (4+4+3)', ['11\'li (6+5)', '10\'lu (4+3+3)', '12\'li (4+4+4)'], 'Yap-rak-dö-ker (4) / bah-çe-miz-de (4) / çı-nar-lar (3): toplam 11 hece, 4+4+3 duraklıdır.'),
  ('Hece ölçüsünde aşağıdakilerden hangisi dikkate alınmaz?', 'Hecenin açık ya da kapalı oluşu', ['Dizedeki hece sayısı', 'Durakların yeri', 'Dizeler arasındaki hece eşitliği'], 'Hece ölçüsü yalnız hece sayısına bakar; hecelerin açık-kapalı (kısa-uzun) olması aruzda önemlidir.'),
  ('Aşağıdaki dizelerden hangisi diğerlerinden farklı sayıda heceden oluşur?', 'Kuşlar uçtu göğe', ['Kara bulut gelir geçer', 'Ay doğdu deniz üstüne', 'Akşam iner köy yoluna'], '\'Kuşlar uçtu göğe\' 6 hecedir; diğer dizelerin her biri 8 hecelidir.'),
  ('Bir şiir 6 dörtlükten oluşuyor ve her dörtlüğün son dizesi aynen tekrarlanıyor. Bu şiirde nakarat olarak kaç dize tekrarlanmıştır?', '6', ['4', '24', '12'], 'Her dörtlükte bir dize nakarattır; 6 dörtlük olduğuna göre bu dize toplam 6 kez geçer.'),
  ('Bir şiirde ilk dörtlüğün son iki dizesi, şiirin diğer bölümlerinde de aynı biçimde tekrarlanıyor. Bu tekrar şiire en çok ne kazandırır?', 'Ahenk ve vurgu', ['Kronolojik düzen', 'Bilimsel kesinlik', 'Belgesel nitelik'], 'Nakarat hem ses bakımından ahenk sağlar hem de şiirin ana duygusunu vurgular.'),
  ('Bir romanın başlığının olay örgüsündeki önemli bir nesneyi ya da simgeyi göstermesi okura en çok ne sağlar?', 'Esere ilişkin bir ipucu', ['Olayların kesin tarihini', 'Yazarın biyografisini', 'Romanın ölçüsünü'], 'Başlık eserin ana simgesini ya da temasını sezdirerek okura yorum ipucu verir.'),
  ('Bir romanda kahramanın yaşadığı dönemin siyasi ve toplumsal olayları ayrıntılı biçimde işleniyor, ama kahraman ve olaylar kurmaca. Bu romanı tarih kitabından ayıran temel unsur hangisidir?', 'Kurmaca olması', ['Tarih bilgisi içermesi', 'Kronolojik sıra izlemesi', 'Düz yazıyla yazılması'], 'Tarih kitabı da düz yazı ve kronolojiktir; romanı ayıran, gerçek arka plan üzerine hayalî kişi ve olayların kurulmasıdır.'),
  ('Bir romanın \'yuvarlak karakter\'lerden oluşmasının okura sağladığı etki nedir?', 'Kişilerin gerçek insanlar gibi çok yönlü algılanması', ['Kişilerin tek bir özellikle hatırlanması', 'Olayların kronolojisinin değişmesi', 'Metnin şiire dönüşmesi'], 'Yuvarlak karakterler çelişkileri ve gelişimleriyle çok boyutlu olduğu için okurda gerçek insan etkisi uyandırır.'),
  ('Bir romanda doğrudan anlatılmayan, ancak olaylardan ve kişilerin davranışlarından çıkarılabilen temel düşünce hangi kavramla ifade edilir?', 'Ana fikir', ['Olay örgüsü', 'Serim', 'Diyalog'], 'Ana fikir eserin vermek istediği temel iletidir; çoğu zaman açıkça söylenmez, okurun çıkarımına bırakılır.'),
  ('Kısa öykü ile roman karşılaştırıldığında, kısa öykünün en belirgin anlatım özelliği hangisidir?', 'Tek bir etki ve yoğunluk üzerinde durması', ['Çok sayıda yan olay örgüsü içermesi', 'Birden çok kuşağın hayatını anlatması', 'Ciltler hâlinde yayımlanması'], 'Kısa öykü, sınırlı uzunluğu nedeniyle tek bir olay, an ya da etki üzerinde yoğunlaşır.'),
  ('Bir öyküde kişilerin konuşmalarında yöresel ağız özelliklerinin kullanılması anlatıya en çok ne kazandırır?', 'Yerellik ve gerçeklik etkisi', ['Bilimsel bir dil', 'Ölçülü bir ahenk', 'Tanrısal bir bakış açısı'], 'Yöresel konuşma özellikleri kişileri yaşadıkları çevreyle birlikte daha gerçekçi kılar.'),
  ('\'Bu şehrin sokakları benim gibi yorgun.\' cümlesindeki benzetmede kendisine benzetilen unsur hangisidir?', 'Konuşan kişi', ['Şehrin dar sokakları', 'Yorgunluk duygusu', '\'Gibi\' edatı'], 'Sokaklar konuşan kişiye benzetilmiştir; sokaklar benzeyen, \'ben\' kendisine benzetilen, \'yorgun\' benzetme yönü, \'gibi\' edattır.'),
  ('\'Dalgalar kıyıya bir şeyler anlatmak ister gibi koşuyordu.\' cümlesindeki kişileştirmeyi oluşturan ifade hangisidir?', 'Anlatmak isteyerek koşmak', ['Kıyı', 'Bir şeyler', 'Dalgaların çokluğu'], 'Bir şey anlatmak istemek ve bu amaçla koşmak insana özgü davranışlardır; dalgalara yüklenmiştir.'),
  ('Aşağıdaki cümlelerin hangisinde edat ve benzetme yönü kullanılmadan kurulmuş iki unsurlu bir benzetme bulunmaz?', 'Kardeşim çok çalışkan bir öğrencidir.', ['Annemin altın kalbi herkese açıktı.', 'Kızın inci dişleri parladı.', 'Gül yanaklı bebek uykuya daldı.'], 'Altın kalp, inci diş, gül yanak benzetmelerinde yalnızca benzeyen ve benzetilen vardır; ilk cümlede benzetme yoktur.'),
  ('\'Elinden bir şey gelmez, kolu kanadı kırık bir kuş gibi.\' cümlesinde benzetmenin yanında kullanılan söz grubu (\'kolu kanadı kırık\') hangi anlam özelliğini taşır?', 'Çaresizliği anlatan mecazlı bir deyimdir', ['Gerçek anlamda bir yaralanmadır', 'Bilimsel bir terimdir', 'Bir efsaneye göndermedir'], '\'Kolu kanadı kırılmak\' deyimi çaresiz, güçsüz kalmayı anlatır; benzetmeyle birlikte anlamı güçlendirir.'),
  ('\'İstanbul\'un kalbi bu meydanda atar.\' cümlesinde \'kalp\' sözcüğü hangi anlamda kullanılmıştır?', 'Bir şeyin en canlı, merkezî yeri', ['Organ olarak yürek', 'Bir tür hastalık', 'Bir sevgi ifadesi'], 'Kalp, mecaz anlamda bir yerin en canlı ve merkezî noktası olarak kullanılmıştır; şehir canlı bir varlığa benzetilmiştir.'),
  ('Bir şair dizesinde \'Ferhat\'ın dağları gibi sabrım tükendi\' diyerek hem benzetme yapıyor hem de bilinen bir öyküye gönderme yapıyor. Bu dizede bulunan iki sanat hangileridir?', 'Teşbih ve telmih', ['Tezat ve tevriye', 'Cinas ve tekrir', 'İntak ve tecrit'], '\'Gibi\' ile benzetme (teşbih) yapılmış, Ferhat ile Şirin öyküsüne gönderme yapılarak telmih kullanılmıştır.'),
  ('Bir makalenin güvenilirliğini en çok azaltan durum hangisidir?', 'Kaynak gösterilmeden kesin yargılarda bulunulması', ['Terimlerin doğru kullanılması', 'Tezin girişte açıkça belirtilmesi', 'Sonuç bölümünde özet yapılması'], 'Makale kanıta dayanan bir türdür; kaynaksız kesin yargılar onun güvenilirliğini zedeler.'),
  ('Bir eleştiri yazısında eleştirmenin yalnızca \'Bu kitabı hiç sevmedim.\' demesi neden yetersiz bulunur?', 'Yargıyı gerekçelendirmediği için', ['Kısa bir cümle olduğu için', 'Birinci kişi ağzıyla söylendiği için', 'Kitabın adını vermediği için'], 'Eleştiri bir değerlendirmedir; beğeni ya da beğenmeme gerekçeleriyle, eserden örneklerle desteklenmelidir.'),
  ('Gezi yazısıyla bir ansiklopedideki şehir maddesi karşılaştırıldığında gezi yazısını ayırt eden özellik hangisidir?', 'Yazarın kişisel izlenimlerini içermesi', ['Gerçek bir yeri anlatması', 'Düz yazıyla yazılması', 'Bilgi vermesi'], 'İki metin de gerçek bir yeri düz yazıyla anlatır ve bilgi verir; gezi yazısını ayıran, gezginin kişisel gözlem ve izlenimleridir.'),
  ('Ünlü yazarların ölümlerinden sonra yayımlanan günlükleri okurlar için hangi açıdan değerlidir?', 'Yazarın iç dünyasını ve yaratım sürecini yansıtması', ['Kurmaca olaylarla dolu olması', 'Bilimsel verileri kanıtlaması', 'Ölçülü ve kafiyeli olması'], 'Günlükler yazarın kendisi için yazdığı samimi kayıtlardır; eserlerin arka planını ve yazarın iç dünyasını anlamaya ışık tutar.'),
  ('Bir otobiyografide yazarın kendi hatalarını da açıkça anlatması metne en çok hangi niteliği kazandırır?', 'İçtenlik', ['Kurmacalık', 'Nesnellik', 'Kronolojiklik'], 'Kişinin kendi kusurlarıyla yüzleşmesi otobiyografide samimiyet ve inandırıcılık yaratır.'),
  ('\'Hatıra\' ile \'otobiyografi\' türlerinde ortak olan özellik hangisidir?', 'Yazarın kendi yaşantısından yola çıkması', ['Olayların hayal ürünü olması', 'Bir başkasının hayatını belgeleriyle anlatması', 'Tiyatro sahnesinde canlandırılması'], 'Her iki türde de yazar kendi yaşadıklarından hareket eder; fark, odak noktası ve kapsamdadır.'),
  ('Bir makale yazarı karşı görüşleri de anıp onları kanıtlarla çürütüyorsa bu tutum makaleye en çok ne kazandırır?', 'İkna gücü', ['Şiirsel ahenk', 'Kurmaca bir dünya', 'Masalsı bir hava'], 'Karşı görüşleri dikkate alıp çürütmek, savunulan tezin daha güçlü ve inandırıcı görünmesini sağlar.'),
  ('\'Elim / Dilim\' sözcükleriyle biten iki dizede redif hangisidir?', '-im', ['-lim', 'El ve dil kökleri', '-li'], 'Birinci tekil iyelik eki \'-im\' her iki sözcükte aynı görevdedir ve rediftir. Kalan \'el\' ve \'dil\' köklerinde yalnız \'l\' sesi ortak olduğundan yarım kafiye vardır.'),
  ('\'Geliyor / Gidiyor\' sözcükleri dize sonlarında kullanıldığında \'-iyor\' eki için ne söylenebilir?', 'Aynı görevli ek olduğu için rediftir', ['Zengin kafiyedir', 'Cinaslı kafiyedir', 'Ölçü birimidir'], '\'-iyor\' şimdiki zaman ekidir ve her iki sözcükte aynı görevdedir; bu yüzden rediftir.'),
  ('\'Dağ / Bağ\' kafiyesinde ortak sesler kaç tanedir ve kafiyenin türü nedir?', 'İki ses; tam kafiye', ['Bir ses; yarım kafiye', 'Üç ses; zengin kafiye', 'Dört ses; cinaslı kafiye'], '\'Dağ\' ve \'bağ\' sözcüklerinde \'a\' ve \'ğ\' sesleri ortaktır; iki ses benzerliği tam kafiyedir.'),
  ('Bir öyküde kahraman bir kokuyu duyunca birden çocukluğundaki bir bayram sabahını hatırlıyor ve anlatı bir süre o güne kayıyor. Hangi tekniğin kullanıldığı söylenebilir?', 'Çağrışıma dayalı geriye dönüş', ['Paralel kurgu', 'Montaj', 'Önceden haber verme'], 'Bir duyusal uyarının (koku) çağrıştırdığı anıyla geçmişe dönülmesi geriye dönüş tekniğidir.'),
  ('Gözlemci bakış açısıyla yazılmış bir öyküde anlatıcının dili için hangisi beklenir?', 'Duygusal yorumdan arınmış, nesnel bir dil', ['Kahramanların düşüncelerini veren bir dil', 'Okura sürekli öğüt veren bir dil', 'Ölçülü ve kafiyeli bir dil'], 'Gözlemci anlatıcı dışarıdan görüleni aktardığı için yorumdan kaçınan, nesnel bir dil kullanır.'),
  ('Bir fablın dersini çıkarmak isteyen öğrenciye öğretmen en çok neye bakmasını önerir?', 'Olayın sonucunun hangi davranışı ödüllendirdiğine', ['Hayvanların renklerine', 'Metnin kaç cümleden oluştuğuna', 'Yazarın doğum yerine'], 'Fablda ders, davranışların sonuçları üzerinden verilir; hangi tutumun ödüllendirildiği ya da cezalandırıldığı dersi gösterir.'),
  ('Bir münazarada bir öğrencinin karşı grubun kişiliğiyle alay etmesi neden puan kaybına yol açar?', 'Kanıta değil kişiye yöneldiği için', ['Konuşmasını kısa tuttuğu için', 'Jüriye seslendiği için', 'Tezini açıkça belirttiği için'], 'Münazarada değerlendirme kanıt ve mantık üzerinden yapılır; kişiye saldırı geçerli bir tartışma yöntemi değildir.'),
  ('Fıkra yazarının bir konuyu mizahi ve iğneleyici bir üslupla ele alması okur üzerinde en çok hangi etkiyi doğurur?', 'Konuyu akılda kalıcı kılar', ['Konuyu bilimsel bir gerçek yapar', 'Konunun tarihini belirler', 'Konuyu masala dönüştürür'], 'Mizah ve ironi, eleştirinin okurda iz bırakmasını ve akılda kalmasını sağlar.'),
  ('Bir röportajın başarılı sayılması için aşağıdakilerden hangisi en önemlidir?', 'Yerinde gözlemle canlı ayrıntılar sunması', ['Yalnızca tek bir soru içermesi', 'Kurmaca kişilere yer vermesi', 'Ölçülü ve kafiyeli yazılması'], 'Röportajın gücü yerinde gözleme ve canlı, gerçek ayrıntılara dayanmasından gelir.'),
  ('Bir öykünün tamamı \'biz\' diliyle, bir köy halkının ortak sesi olarak anlatılıyor. Bu anlatıcı için en uygun adlandırma hangisidir?', 'Birinci çoğul kişi anlatıcı', ['Tekil ilahi anlatıcı', 'Kamera gibi gözlemci anlatıcı', 'İkinci tekil kişi anlatıcı'], 'Anlatım \'biz\' ile yapıldığı için anlatıcı birinci çoğul kişidir; topluluğun ortak bakışını yansıtır.'),
  ('Bir paragrafta hem kişinin dış görünüşü hem de yaptığı hareketler anlatılıyorsa paragrafın anlatım biçimi için en doğru değerlendirme hangisidir?', 'Betimleme ve öyküleme iç içedir', ['Yalnızca tartışmacı anlatım vardır', 'Yalnızca açıklayıcı anlatım vardır', 'Hiçbir anlatım biçimi kullanılmamıştır'], 'Dış görünüşün tasviri betimleme, hareketlerin aktarımı öykülemedir; iki biçim aynı paragrafta birleşebilir.'),
  ('Bir komedide kahramanın kendini çok bilgili sanıp sürekli yanlış bilgiler vermesi hangi tür gülünçlüğe örnektir?', 'Karakter gülünçlüğü', ['Olay gülünçlüğü', 'Söz gülünçlüğü', 'Durum trajedisi'], 'Gülme, kişinin abartılmış bir zaafından (kendini bilgili sanma) doğduğu için karakter gülünçlüğüdür.'),
];
